type FeedCursor = string | null; // opaque: base64(score, postId)

async function fetchFeed(cursor: FeedCursor, limit = 20) {
  const res = await api.get("/feed/home", { params: { cursor, limit } });
  // Server returns stable order + next cursor. Never use offset.
  // On ranker timeout, server sets degraded: true and falls back to chrono.
  return res.data as { items: Post[], nextCursor: FeedCursor, degraded: boolean };
}

async function createPost(text: string, idemKey: string) {
  const tempId = `temp:${idemKey}`;
  store.optimisticInsert({ id: tempId, text, status: "sending" });
  try {
    const saved = await api.post("/posts", { text }, { headers: { "Idempotency-Key": idemKey } });
    store.reconcile(tempId, saved); // swap temp ID, keep scroll position
  } catch (e) {
    store.markFailed(tempId); // keep draft + explicit retry, do not silently drop
  }
}
